'use client';
import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import Link from 'next/link';
import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { ArrowRight, BarChart3, BellRing, CalendarDays, Check, ChevronRight, ClipboardCheck, ClipboardList, Clock3, CreditCard, DatabaseBackup, Headphones, Home, LayoutDashboard, LogOut, Menu, RefreshCw, Settings2, ShieldAlert, ShieldCheck, UserRoundX, Users, X } from 'lucide-react';
import { consentVersions, legalDocuments, type LegalDocument } from '@keiba/domain';
import { RaceManager } from './race-manager';
import { AssessmentEditor } from './assessment-editor';
import { PublishedPrediction } from './prediction-editor';
import { AdminSettings } from './admin-settings';
import { AdminNotifications } from './admin-notifications';
import { AdminResults, StatsPage } from './results';
import { AdminBilling, BillingAccount, PlansPage } from './billing';
import { MemberNotifications } from './member-notifications';
import { RaceArchive } from './race-archive';
import { AdminIncidents } from './admin-incidents';
import { AdminBackups } from './admin-backups';
import { AccountClosure } from './account-closure';
import { AdminAccountClosures } from './admin-account-closures';
import { AdminReadiness } from './admin-readiness';
import { FreeReportManager, RegistrationBenefit } from './free-reports';
import { PublicationSchedules } from './publication-schedules';
import { AcquisitionManager } from './acquisition-manager';

type Preferences = { predictions: boolean; changes: boolean; articles: boolean; billing: boolean };
type PublicConfig = { localOnly: boolean; launchMode: 'FREE_REGISTRATION' | 'FULL'; capabilities: { emailRegistration: true; freeContent: true; lineLogin: boolean; lineNotifications: boolean; billing: boolean }; lineEnabled: boolean; lineNotificationsEnabled: boolean };
type Me = { id: string; email: string | null; emailVerified: boolean; hasPassword: boolean; registrationMethod: string; displayName: string; role: string; aal: number; mfaEnabled: boolean; mfaRequired: boolean; lineLinked: boolean; lineNotificationState: 'NOT_LINKED' | 'BLOCKED' | 'DISABLED' | 'READY'; lineNotificationReady: boolean; preferences: Preferences; entitlements: { planCode: string; startsAt: string; endsAt: string; raceDate?: string | null }[]; consents: { documentType: string; version: string; acceptedAt: string }[] };
type Race = { id: string; name: string; venue: string; number: number; raceDate: string; startsAt: string; status: string };
type Announcement = { id: string; version: number; publishedAt: string; race: Race };
type FunnelCounts = { registered: number; identityReady: number; lineReady: number; planViewed: number; checkoutReviewed: number; paid: number };
type AcquisitionRow = { source: string; medium: string | null; campaign: string | null; registered: number; paid: number };
type Summary = { members: number; entitled: number; races: number; auditCount: number; queuedNotifications: number; racesNeedingPrediction: number; resultsPending: number; operations: { predictionPublicationEnabled: boolean; csvImportEnabled: boolean; lineNotificationsEnabled: boolean; lineLoginEnabled: boolean; newPurchasesEnabled: boolean }; funnel: { all: FunnelCounts; last30Days: FunnelCounts & { cohortStartsAt: string }; trackingStartsAt: string | null }; acquisition: { last30Days: AcquisitionRow[]; cohortStartsAt: string; legacyMembers: number } };
const roleLabels: Record<string, string> = { MEMBER: '会員', EXPERT: '専門家', EDITOR: '編集担当', OPERATOR: '運営担当', ADMIN: '管理者' };
const formatDate = (date: string) => new Intl.DateTimeFormat('ja-JP', { timeZone: 'Asia/Tokyo', month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(date));
async function api<T>(path: string, method = 'GET', body?: unknown): Promise<T> {
  const response = await fetch(`/api/v1/${path}`, { method, headers: body ? { 'Content-Type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined, cache: 'no-store' });
  const result = await response.json();
  if (!response.ok) throw new Error(result.message ?? '処理に失敗しました。');
  return result as T;
}
function Notice({ text, error = false }: { text: string; error?: boolean }) { return text ? <div className={`notice ${error ? 'error' : ''}`} role={error ? 'alert' : 'status'}>{text}</div> : null; }
function Heading({ eyebrow, title, description }: { eyebrow: string; title: string; description?: string }) { return <div className="page-heading"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description && <p>{description}</p>}</div>; }
function Empty({ title, children }: { title: string; children: ReactNode }) { return <div className="empty"><CalendarDays size={32} strokeWidth={1.3} /><h3>{title}</h3><p>{children}</p></div>; }
function Unavailable({ title, detail }: { title: string; detail: string }) { return <><Heading eyebrow="COMING SOON" title={title} description={detail} /><Link className="button" href="/">ホームへ <ArrowRight size={17} /></Link></>; }

export function MediaApp() {
  const path = usePathname(); const router = useRouter();
  const [me, setMe] = useState<Me | null>(null); const [unreadNotifications, setUnreadNotifications] = useState(0); const [loading, setLoading] = useState(true); const [menu, setMenu] = useState(false);
  const [config, setConfig] = useState<PublicConfig>({ localOnly: false, launchMode: 'FREE_REGISTRATION', capabilities: { emailRegistration: true, freeContent: true, lineLogin: false, lineNotifications: false, billing: false }, lineEnabled: false, lineNotificationsEnabled: false });
  const [error, setError] = useState('');
  const loadMe = useCallback(async () => {
    setLoading(true);
    try { const account = await api<Me>('me'); setMe(account); try { const notifications = await api<{ unreadCount: number }>('me/notifications?limit=1'); setUnreadNotifications(notifications.unreadCount); } catch { setUnreadNotifications(0); } } catch { setMe(null); setUnreadNotifications(0); } finally { setLoading(false); }
  }, []);
  useEffect(() => { api<PublicConfig>('auth/config').then(setConfig).catch(() => undefined); }, []);
  useEffect(() => { void loadMe(); }, [loadMe, path]);
  const authPage = ['/login', '/register', '/register/line', '/verify-email', '/forgot-password', '/reset-password'].includes(path);
  const protectedPage = ['/account', '/notifications', '/security', '/expert', '/admin', '/admin/users', '/admin/audit', '/admin/races', '/admin/free-reports', '/admin/publication-schedules', '/admin/acquisition', '/admin/settings', '/admin/notifications', '/admin/results', '/admin/billing', '/admin/incidents', '/admin/backups', '/admin/account-closures', '/admin/readiness'].includes(path);
  const nav = [ { href: '/', label: 'ホーム', Icon: Home }, { href: '/races', label: 'レース一覧', Icon: CalendarDays }, ...(me ? [{ href: '/notifications', label: 'お知らせ', Icon: BellRing }] : []), { href: '/results', label: '予想成績', Icon: BarChart3 }, ...(config.capabilities.billing ? [{ href: '/plans', label: '料金プラン', Icon: CreditCard }] : []), { href: '/account', label: 'マイページ', Icon: Settings2 }, { href: '/security', label: 'セキュリティ', Icon: ShieldCheck },
    ...(me && ['ADMIN', 'EXPERT'].includes(me.role) ? [{ href: '/expert', label: '担当レース', Icon: ClipboardList }] : []),
    ...(me && ['ADMIN', 'OPERATOR'].includes(me.role) ? [{ href: '/admin', label: '管理ダッシュボード', Icon: LayoutDashboard }, { href: '/admin/races', label: 'レース管理', Icon: CalendarDays }, { href: '/admin/free-reports', label: '無料会員向け配信', Icon: Headphones }, { href: '/admin/publication-schedules', label: '配信予約・アラート', Icon: Clock3 }, { href: '/admin/results', label: '結果・成績管理', Icon: BarChart3 }, { href: '/admin/notifications', label: '通知運用', Icon: BellRing }, { href: '/admin/incidents', label: '障害対応', Icon: ShieldAlert }] : []),
    ...(me?.role === 'ADMIN' ? [{ href: '/admin/acquisition', label: 'キャンペーン・流入管理', Icon: BarChart3 }, { href: '/admin/readiness', label: '本番準備チェック', Icon: ClipboardCheck }, { href: '/admin/backups', label: 'バックアップ確認', Icon: DatabaseBackup }, { href: '/admin/account-closures', label: '退会・保持記録', Icon: UserRoundX }, { href: '/admin/billing', label: '契約・請求管理', Icon: CreditCard }, { href: '/admin/settings', label: '運用・連携設定', Icon: Settings2 }, { href: '/admin/users', label: '会員管理', Icon: Users }, { href: '/admin/audit', label: '操作履歴', Icon: Clock3 }] : []) ];
  async function logout() { try { await api('auth/logout', 'POST'); setMe(null); setUnreadNotifications(0); router.push('/login'); } catch (e) { setError((e as Error).message); } }
  return <div className="app-shell">
    <a href="#main" className="skip-link">本文へ移動</a>
    <aside className={`sidebar ${menu ? 'open' : ''}`}>
      <Link href="/" className="brand" onClick={() => setMenu(false)}><span className="brand-mark">K<span>／</span></span><span>競馬会員メディア<small>MEMBER’S DESK</small></span></Link>
      <button className="close-menu icon-button" aria-label="メニューを閉じる" onClick={() => setMenu(false)}><X /></button>
      <div className="nav-caption">マイメニュー</div>
      <nav aria-label="メインメニュー">{nav.map(({ href, label, Icon }) => <Link key={href} href={href} className={path === href ? 'nav-link active' : 'nav-link'} aria-current={path === href ? 'page' : undefined} onClick={() => setMenu(false)}><Icon size={19} /><span>{label}</span>{href === '/notifications' && unreadNotifications > 0 && <span className="nav-badge" aria-label={`${unreadNotifications}件の未読`}>{unreadNotifications > 99 ? '99+' : unreadNotifications}</span>}{path === href && <ChevronRight size={16} />}</Link>)}</nav>
      <div className="sidebar-bottom"><div className="edition">{config.localOnly ? '開発環境' : config.launchMode === 'FREE_REGISTRATION' ? '先行公開' : '会員サービス'} <span>無料登録</span></div><p>{config.capabilities.lineLogin ? 'LINE・メールから無料会員へ' : 'メールから無料会員へ'}<br />登録できます。</p><div className="legal-links"><Link href="/terms">利用規約</Link><Link href="/privacy">プライバシー</Link></div></div>
    </aside>
    {menu && <button className="menu-overlay" aria-label="メニューを閉じる" onClick={() => setMenu(false)} />}
    <div className="workspace">
      <header className="topbar"><div className="topbar-left"><button className="mobile-menu icon-button" aria-label="メニューを開く" onClick={() => setMenu(true)}><Menu /></button><span>MEMBER’S DESK</span><span className="topbar-divider">/</span><span>{nav.find(n => n.href === path)?.label ?? 'アカウント'}</span></div>
        <div className="topbar-right">{me ? <><Link className="icon-button notification-shortcut" href="/notifications" aria-label={unreadNotifications > 0 ? `お知らせ、未読${unreadNotifications}件` : 'お知らせ'}><BellRing size={19} />{unreadNotifications > 0 && <span>{unreadNotifications > 99 ? '99+' : unreadNotifications}</span>}</Link><span className="role-tag">{roleLabels[me.role]}</span><span className="user-name">{me.displayName}</span><button className="icon-button" title="ログアウト" aria-label="ログアウト" onClick={() => void logout()}><LogOut size={19} /></button></> : <><Link className="text-link" href="/login">ログイン</Link><Link className="button small" href="/register">無料会員登録</Link></>}</div>
      </header>
      <main id="main" className={authPage ? 'main-content auth-content' : 'main-content'}>
        <Notice text={error} error />
        {path === '/register/line' ? config.capabilities.lineLogin ? <LineRegistration onSuccess={loadMe} /> : <Unavailable title="LINE登録は準備中です" detail="現在はメールアドレスで無料会員登録を受け付けています。" /> : path === '/verify-email' ? <EmailVerification onSuccess={loadMe} /> : authPage ? <AuthForm key={path} path={path} onSuccess={loadMe} lineEnabled={config.lineEnabled} localOnly={config.localOnly} /> : path === '/terms' || path === '/privacy' ? <Policy privacy={path === '/privacy'} /> : path === '/results' ? <StatsPage /> : loading ? <div className="loading" role="status">読み込み中…</div> : protectedPage && !me ? <><Heading eyebrow="ACCOUNT" title="ログインが必要です" description="アカウントの情報を確認するにはログインしてください。" /><Link className="button" href="/login">ログインへ <ArrowRight size={17} /></Link></> : path === '/plans' ? config.capabilities.billing ? <PlansPage loggedIn={!!me} purchaseReady={!!me?.emailVerified && !!me?.hasPassword} refresh={loadMe} /> : <Unavailable title="有料プランは準備中です" detail="現在は無料会員向けの情報を提供しています。" /> : path === '/races' ? <RaceArchive entitlements={me?.entitlements} /> : path === '/notifications' && me ? <MemberNotifications /> : path === '/account' && me ? <Account me={me} refresh={loadMe} capabilities={config.capabilities} /> : path === '/security' && me ? <Security me={me} refresh={loadMe} /> : path === '/admin/free-reports' && me ? <FreeReportManager /> : path.startsWith('/admin') && me ? <Admin me={me} path={path} /> : path === '/expert' && me ? <Expert me={me} /> : path.startsWith('/races/') ? <PublishedPrediction raceId={path.split('/')[2]} /> : <HomePage me={me} unreadNotifications={unreadNotifications} capabilities={config.capabilities} />}
      </main>
      <footer className="footer"><span>競馬会員メディア</span><span>20歳未満の方は馬券を購入できません。</span></footer>
    </div>
  </div>;
}

function HomePage({ me, unreadNotifications, capabilities }: { me: Me | null; unreadNotifications: number; capabilities: PublicConfig['capabilities'] }) {
  const [races, setRaces] = useState<Race[]>([]); const [announcements, setAnnouncements] = useState<Announcement[]>([]); const [error, setError] = useState(''); const [loading, setLoading] = useState(true);
  useEffect(() => { Promise.all([api<{ items: Race[] }>('races'), api<{ items: Announcement[] }>('announcements')]).then(([raceData, announcementData]) => { setRaces(raceData.items); setAnnouncements(announcementData.items); }).catch(e => setError(e.message)).finally(() => setLoading(false)); }, []);
  const now = new Date(); const paid = !!me?.entitlements.some(item => new Date(item.startsAt) <= now && now < new Date(item.endsAt));
  const nextAction = unreadNotifications > 0 ? { href: '/notifications', title: '未読のお知らせを確認', detail: `${unreadNotifications}件の新しい告知・公開情報があります。` } : me && capabilities.lineNotifications && !me.lineNotificationReady ? { href: '/account', title: 'LINE通知を設定', detail: '対象レース告知と最終予想の公開を受け取れるようにします。' } : me && capabilities.billing && !paid ? { href: '/plans', title: '料金プランを確認', detail: '有料予想の提供内容と料金を確認できます。' } : { href: '/races', title: '公開中のレースを確認', detail: '開催日と公開状態からレースを探せます。' };
  return <>
    <Heading eyebrow="RACE & INSIGHT" title={me ? `${me.displayName}さん、こんにちは。` : 'レースを、もっと深く。'} description="レース情報と専門家の評価を、ここから。" />
    {me && <section className="member-dashboard" aria-labelledby="member-dashboard-title"><div className="member-dashboard-heading"><div><span className="eyebrow">YOUR STATUS</span><h2 id="member-dashboard-title">会員ステータス</h2></div><Link className="text-link" href="/account">設定を確認 <ChevronRight size={16} /></Link></div><div className="member-status-grid"><Link href="/notifications" className="member-status-card"><BellRing size={20} /><span>未読のお知らせ</span><strong>{unreadNotifications}<small>件</small></strong></Link>{capabilities.lineNotifications && <Link href="/account" className="member-status-card"><Check size={20} /><span>LINE通知</span><strong>{me.lineNotificationReady ? '受信準備済み' : '設定が必要'}</strong></Link>}<Link href={paid || !capabilities.billing ? '/account' : '/plans'} className="member-status-card"><CreditCard size={20} /><span>会員プラン</span><strong>{paid ? '有料閲覧中' : '無料会員'}</strong></Link></div><div className="member-next-action"><div><span>次におすすめ</span><strong>{nextAction.title}</strong><small>{nextAction.detail}</small></div><Link className="button" href={nextAction.href}>確認する <ArrowRight size={17} /></Link></div></section>}
    {me && <RegistrationBenefit />}
    {announcements.length > 0 && <section className="panel announcement-feed"><div className="panel-heading"><div><span className="eyebrow">RACE ANNOUNCEMENT</span><h2>予想対象レースのお知らせ</h2></div><span className="count-tag">{announcements.length} 件</span></div><div className="race-list">{announcements.map(item => <div className="race-row" key={item.id}><div className="race-number">{item.race.number}<small>R</small></div><div className="race-info"><span className="muted">{item.race.raceDate} · {item.race.venue} · 発走 {formatDate(item.race.startsAt)} JST</span><h3>{item.race.name}</h3></div><Link className="button secondary small" href={`/races/${item.race.id}`}>詳細を見る</Link></div>)}</div></section>}
    <div className="home-grid"><section className="panel race-panel"><div className="panel-heading"><div><span className="eyebrow">RACE SCHEDULE</span><h2>対象レース</h2></div><span className="count-tag">{races.length} レース</span></div><Notice text={error} error />
      {loading ? <div className="empty" role="status">レース情報を読み込み中…</div> : races.length ? <div className="race-list">{races.map(race => <div className="race-row" key={race.id}><div className="race-number">{race.number}<small>R</small></div><div className="race-info"><span className="muted">{race.venue} · {formatDate(race.startsAt)} JST</span><h3>{race.name}</h3></div><Link className="button secondary small" href={`/races/${race.id}`}>予想を見る</Link></div>)}</div> : !error && <Empty title="対象レースはまだありません">開催日の準備が整うと、こちらに表示されます。</Empty>}
      <div className="panel-foot"><Clock3 size={16} />公開済みの予想と訂正履歴を確認できます。<Link className="text-link" href="/races">レース一覧へ</Link></div>
    </section>
    <aside className="home-side"><section className="membership"><span className="eyebrow">YOUR MEMBERSHIP</span><h2>{me ? 'あなたの会員情報' : '無料会員で始める'}</h2><div className="membership-level">{me?.entitlements.some(e => new Date(e.startsAt) <= new Date()) ? '閲覧権限あり' : '無料会員'}<span>MEMBER</span></div><p>{me ? '通知設定やセキュリティ設定を、マイページで確認できます。' : 'アカウントを作成して、レース情報を確認しましょう。'}</p><Link className="button light" href={me ? '/account' : '/register'}>{me ? 'マイページへ' : '無料会員登録'}<ArrowRight size={17} /></Link></section>
      <section className="plain-note"><ShieldCheck size={22} /><h3>予想の履歴を大切に</h3><p>公開した予想は履歴として残し、訂正内容や成績も確認できる仕組みを準備しています。</p></section></aside></div>
    <section className="getting-ready"><span className="section-index">01</span><div><h2>まずはアカウントの準備から</h2><p>登録情報・通知の受け取り方・二段階認証を設定できます。</p></div><Link href={me ? '/security' : '/login'} className="text-link">設定を確認 <ArrowRight size={16} /></Link></section>
  </>;
}

function AuthForm({ path, onSuccess, lineEnabled, localOnly }: { path: string; onSuccess: () => Promise<void>; lineEnabled: boolean; localOnly: boolean }) {
  const router = useRouter(); const search = useSearchParams(); const registration = path === '/register'; const forgot = path === '/forgot-password'; const reset = path === '/reset-password';
  const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  useEffect(() => { if (path === '/login' && search.get('closed') === '1') setMessage('退会手続きが完了し、すべての端末からログアウトしました。'); }, [path, search]);
  const acquisition = registration ? { source: search.get('utm_source') || undefined, medium: search.get('utm_medium') || undefined, campaign: search.get('utm_campaign') || undefined, content: search.get('utm_content') || undefined, term: search.get('utm_term') || undefined, referralCode: search.get('ref') || undefined, landingPath: '/register' } : undefined;
  async function lineLogin() { setBusy(true); setError(''); try { const value = await api<{ authorizationUrl: string }>('auth/line/start', 'POST', { purpose: 'LOGIN' }); window.location.assign(value.authorizationUrl); } catch (e) { setError((e as Error).message); setBusy(false); } }
  async function lineRegister() { setBusy(true); setError(''); try { const value = await api<{ authorizationUrl: string }>('auth/line/start', 'POST', { purpose: 'REGISTER', acquisition }); window.location.assign(value.authorizationUrl); } catch (e) { setError((e as Error).message); setBusy(false); } }
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError(''); setMessage('');
    const form = new FormData(event.currentTarget);
    try {
      if (forgot) { const result = await api<{ message: string }>('auth/password/request', 'POST', { email: form.get('email') }); setMessage(result.message); }
      else if (reset) { const token = new URL(window.location.href).searchParams.get('token'); await api('auth/password/reset', 'POST', { token, password: form.get('password') }); setMessage('パスワードを再設定しました。新しいパスワードでログインしてください。'); }
      else {
        await api(registration ? 'auth/register' : 'auth/login', 'POST', { email: form.get('email'), password: form.get('password'), ...(registration ? { displayName: form.get('displayName'), adult: form.get('adult') === 'on', terms: form.get('terms') === 'on', privacy: form.get('privacy') === 'on', termsVersion: consentVersions.terms, privacyVersion: consentVersions.privacy, acquisition } : {}) });
        if (registration) router.push('/verify-email?sent=1'); else { await onSuccess(); router.push('/account'); }
      }
    } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  }
  const title = registration ? '無料会員登録' : forgot ? 'パスワードをお忘れの方' : reset ? '新しいパスワードを設定' : 'おかえりなさい';
  return <div className="auth-grid"><div className="auth-intro"><span className="eyebrow">MEMBER’S DESK</span><h1>{title}</h1><p>{registration ? 'あなたのアカウントを作成して、レース情報を確認しましょう。' : forgot ? '登録したメールアドレスを入力してください。' : reset ? '12文字以上のパスワードを設定してください。' : 'メールアドレスとパスワードでログインしてください。'}</p><div className="auth-aside"><ShieldCheck size={24} /><strong>安心して使えるアカウントに</strong><p>管理者と専門家には、認証アプリによる二段階認証が必要です。</p></div></div>
    <section className="panel auth-panel"><form onSubmit={submit}>
      <Notice text={error} error /><Notice text={message} />
      {registration && lineEnabled && <><button type="button" className="button line-button full" disabled={busy} onClick={() => void lineRegister()}>LINEで無料登録<ArrowRight size={17} /></button><div className="auth-divider"><span>またはメールで登録</span></div></>}
      {registration && <label className="field">表示名<input name="displayName" autoComplete="nickname" maxLength={60} required placeholder="例：山田 太郎" /></label>}
      {!reset && <label className="field">メールアドレス<input type="email" name="email" autoComplete="email" required maxLength={254} placeholder="name@example.com" /></label>}
      {!forgot && <label className="field"><span id="password-label">パスワード</span><input type="password" name="password" aria-labelledby="password-label" aria-describedby={registration || reset ? 'password-hint' : undefined} autoComplete={registration || reset ? 'new-password' : 'current-password'} required minLength={registration || reset ? 12 : 1} maxLength={128} />{(registration || reset) && <small id="password-hint">12文字以上で設定してください。</small>}</label>}
      {registration && <div className="consents"><label><input type="checkbox" name="adult" required /><span>20歳以上です。</span></label><label><input type="checkbox" name="terms" required /><span><Link href="/terms" target="_blank">{legalDocumentLabel(legalDocuments.terms)}</Link>に同意します。</span></label><label><input type="checkbox" name="privacy" required /><span><Link href="/privacy" target="_blank">{legalDocumentLabel(legalDocuments.privacy)}</Link>に同意します。</span></label></div>}
      <button className="button full" disabled={busy}>{busy ? '処理中…' : registration ? '同意して登録する' : forgot ? '再設定の案内を送る' : reset ? 'パスワードを更新' : 'ログイン'}<ArrowRight size={17} /></button>
      {!registration && !forgot && !reset && lineEnabled && <button type="button" className="button secondary full" disabled={busy} onClick={() => void lineLogin()}>LINEでログイン<ArrowRight size={17} /></button>}
      {!registration && !forgot && !reset && <Link href="/forgot-password" className="form-link">パスワードをお忘れですか？</Link>}
      <div className="auth-switch">{registration ? <>すでに登録済みの方は <Link href="/login">ログイン</Link></> : forgot || reset ? <Link href="/login">ログインへ戻る</Link> : <>アカウントをお持ちでない方は <Link href="/register">無料会員登録</Link></>}</div>
    </form>{localOnly && <p className="development-note">開発用の環境です。実際の個人情報や、他のサービスで使用しているパスワードは入力しないでください。</p>}</section>
  </div>;
}

function LineRegistration({ onSuccess }: { onSuccess: () => Promise<void> }) {
  const router = useRouter(); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(''); const form = new FormData(event.currentTarget); const token = new URL(window.location.href).searchParams.get('token'); try {
    await api('auth/line/register', 'POST', { token, displayName: form.get('displayName'), adult: form.get('adult') === 'on', terms: form.get('terms') === 'on', privacy: form.get('privacy') === 'on', termsVersion: consentVersions.terms, privacyVersion: consentVersions.privacy });
    await onSuccess(); router.push('/account?line=registered');
  } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  return <div className="auth-grid"><div className="auth-intro"><span className="eyebrow">LINE REGISTRATION</span><h1>無料登録を完了</h1><p>表示名と必要な同意を確認すると、LINEでログインできる無料会員になります。</p></div><section className="panel auth-panel"><form onSubmit={submit}><Notice text={error} error /><label className="field">表示名<input name="displayName" autoComplete="nickname" maxLength={60} required /></label><div className="consents"><label><input type="checkbox" name="adult" required /><span>20歳以上です。</span></label><label><input type="checkbox" name="terms" required /><span><Link href="/terms" target="_blank">{legalDocumentLabel(legalDocuments.terms)}</Link>に同意します。</span></label><label><input type="checkbox" name="privacy" required /><span><Link href="/privacy" target="_blank">{legalDocumentLabel(legalDocuments.privacy)}</Link>に同意します。</span></label></div><button className="button line-button full" disabled={busy}>{busy ? '登録中…' : '同意してLINE無料登録を完了'}<ArrowRight size={17} /></button></form></section></div>;
}

function EmailVerification({ onSuccess }: { onSuccess: () => Promise<void> }) {
  const router = useRouter(); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [checking, setChecking] = useState(true);
  useEffect(() => { const token = new URL(window.location.href).searchParams.get('token'); if (!token) { setChecking(false); return; } api('auth/email/verify', 'POST', { token }).then(async () => { await onSuccess(); router.replace('/account?email=verified'); }).catch(e => { setError(e.message); setChecking(false); }); }, [onSuccess, router]);
  async function resend(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(''); const form = new FormData(event.currentTarget); try { const result = await api<{ message: string }>('auth/email/resend', 'POST', { email: form.get('email') }); setMessage(result.message); } catch (e) { setError((e as Error).message); } }
  return <div className="auth-grid"><div className="auth-intro"><span className="eyebrow">EMAIL VERIFICATION</span><h1>メールアドレスを確認</h1><p>確認メールのURLを開くと無料登録が完了します。</p></div><section className="panel auth-panel"><Notice text={error} error /><Notice text={message} />{checking ? <p role="status">確認中…</p> : <form onSubmit={resend}><p className="form-note">メールが届かない場合は、登録したアドレスへ再送できます。</p><label className="field">メールアドレス<input name="email" type="email" autoComplete="email" required /></label><button className="button full">確認メールを再送</button></form>}</section></div>;
}

function Account({ me, refresh, capabilities }: { me: Me; refresh: () => Promise<void>; capabilities: PublicConfig['capabilities'] }) {
  const [preferences, setPreferences] = useState(me.preferences); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  useEffect(() => { const url = new URL(window.location.href); const line = url.searchParams.get('line'); const email = url.searchParams.get('email'); if (line === 'linked') setMessage('LINEアカウントを連携しました。'); else if (line === 'login') setMessage('LINEでログインしました。'); else if (line === 'registered') setMessage('LINE無料登録が完了しました。'); else if (email === 'verified') setMessage('メールアドレスの確認が完了しました。'); }, []);
  async function save(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); setMessage(''); try { await api('me/preferences', 'PATCH', preferences); setMessage('通知設定を保存しました。'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function enableRaceNotifications() { setBusy(true); setError(''); setMessage(''); const next = { ...preferences, predictions: true }; try { await api('me/preferences', 'PATCH', next); setPreferences(next); await refresh(); setMessage('対象レース告知と最終予想の通知を有効にしました。'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function linkLine() { setBusy(true); setError(''); try { const value = await api<{ authorizationUrl: string }>('auth/line/start', 'POST', { purpose: 'LINK' }); window.location.assign(value.authorizationUrl); } catch (e) { setError((e as Error).message); setBusy(false); } }
  async function unlinkLine() { setBusy(true); setError(''); setMessage(''); try { await api('auth/line/unlink', 'POST'); await refresh(); setMessage('LINE連携を解除しました。'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function fallback(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(''); setMessage(''); const form = new FormData(event.currentTarget); try { const result = await api<{ message: string }>('auth/email/fallback', 'POST', { email: form.get('email'), password: form.get('password') }); setMessage(result.message); event.currentTarget.reset(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  const hasPaidAccess = me.entitlements.length > 0;
  const lineStatus = ({ READY: '受信できます', DISABLED: '通知がオフです', BLOCKED: 'LINE側で受信できません', NOT_LINKED: '未連携です' } as const)[me.lineNotificationState];
  const lineAvailable = capabilities.lineLogin || capabilities.lineNotifications;
  const onboardingTotal = 2 + Number(lineAvailable) + Number(capabilities.billing);
  const onboardingDone = 1 + Number(me.emailVerified && me.hasPassword) + Number(lineAvailable && me.lineNotificationReady) + Number(capabilities.billing && hasPaidAccess);
  const preferenceKeys = (capabilities.billing ? ['predictions', 'changes', 'articles', 'billing'] : ['predictions', 'changes', 'articles']) as (keyof Preferences)[];
  return <><Heading eyebrow="MY ACCOUNT" title="マイページ" description="会員情報と、通知の受け取り方を確認できます。" /><Notice text={error} error /><Notice text={message} />
    <section className="panel onboarding-panel"><div className="panel-heading"><div><span className="eyebrow">GETTING STARTED</span><h2>利用準備</h2></div><span className="status-tag">{onboardingDone} / {onboardingTotal}</span></div><div className="onboarding-list">
      <div className="onboarding-row complete"><span className="onboarding-mark"><Check size={18} /></span><div><strong>無料会員登録</strong><small>登録と必要な同意が完了しています。</small></div><span className="status-tag">完了</span></div>
      {lineAvailable && <div className={`onboarding-row ${me.lineNotificationReady ? 'complete' : ''}`}><span className="onboarding-mark">{me.lineNotificationReady ? <Check size={18} /> : '2'}</span><div><strong>LINEでレース情報を受け取る</strong><small>{lineStatus} 対象レース告知と最終予想の公開をLINEでお知らせします。</small></div>{me.lineNotificationState === 'NOT_LINKED' ? <button type="button" className="button line-button small" disabled={busy} onClick={() => void linkLine()}>LINEを連携</button> : me.lineNotificationState === 'DISABLED' ? <button type="button" className="button secondary small" disabled={busy} onClick={() => void enableRaceNotifications()}>通知をオン</button> : me.lineNotificationState === 'BLOCKED' ? <span className="status-tag warning">公式LINEを再追加</span> : <span className="status-tag">受信準備済み</span>}</div>}
      <div className={`onboarding-row ${me.emailVerified && me.hasPassword ? 'complete' : ''}`}><span className="onboarding-mark">{me.emailVerified && me.hasPassword ? <Check size={18} /> : '3'}</span><div><strong>予備のログイン方法</strong><small>{me.emailVerified && me.hasPassword ? '確認済みメールとパスワードを設定済みです。' : 'LINEを使えない場合のログイン手段を設定します。'}</small></div>{me.emailVerified && me.hasPassword ? <span className="status-tag">設定済み</span> : <a className="button secondary small" href="#fallback-login">設定する</a>}</div>
      {capabilities.billing && <div className={`onboarding-row ${hasPaidAccess ? 'complete' : ''}`}><span className="onboarding-mark">{hasPaidAccess ? <Check size={18} /> : '4'}</span><div><strong>有料予想を見る</strong><small>{hasPaidAccess ? '現在、有料予想を閲覧できます。' : '無料会員のまま料金と内容を確認できます。'}</small></div>{hasPaidAccess ? <span className="status-tag">利用中</span> : <Link className="button secondary small" href="/plans">料金を確認</Link>}</div>}
    </div></section>
    <div className="two-columns"><section className="panel"><div className="panel-heading"><h2>会員情報</h2><span className="role-tag">{roleLabels[me.role]}</span></div><dl className="details"><div><dt>表示名</dt><dd>{me.displayName}</dd></div><div><dt>メールアドレス</dt><dd>{me.email ?? '未設定'}<small>{me.emailVerified ? '確認済み' : me.email ? '確認待ち' : 'ログイン用メールアドレスを設定できます。'}</small></dd></div><div><dt>二段階認証</dt><dd>{me.mfaEnabled ? '設定済み' : '未設定'} <Link href="/security">設定する</Link></dd></div>{lineAvailable && <div><dt>LINE連携</dt><dd>{me.lineLinked ? '連携済み' : '未連携'}<small>{lineStatus}{me.lineNotificationState === 'BLOCKED' && ' LINE公式アカウントを再追加すると受信を再開できます。'}</small><button type="button" className="button secondary small" disabled={busy} onClick={() => void (me.lineLinked ? unlinkLine() : linkLine())}>{me.lineLinked ? '連携を解除' : 'LINEを連携'}</button></dd></div>}</dl></section>
    <section className="panel"><div className="panel-heading"><h2>閲覧権限</h2><ShieldCheck size={20} /></div>{me.entitlements.length ? <ul className="entitlement-list">{me.entitlements.map((e, i) => <li key={i}><strong>{e.planCode}</strong><span>{formatDate(e.startsAt)} 〜 {formatDate(e.endsAt)} JST</span></li>)}</ul> : <div className="panel-body"><h3>無料会員</h3><p className="muted">無料会員向けのレース情報と公開コンテンツを確認できます。{capabilities.billing && <Link className="text-link" href="/plans">料金プランを見る</Link>}</p></div>}<div className="panel-foot"><button className="text-link" onClick={() => void refresh()}>最新の状態を確認</button></div></section></div>
    {!me.emailVerified && <section className="panel" id="fallback-login"><div className="panel-heading"><h2>予備のログイン方法</h2><ShieldCheck size={20} /></div><form className="panel-body" onSubmit={fallback}><p className="form-note">有料プランの申込やLINE連携の解除には、確認済みメールアドレスとパスワードが必要です。</p><label className="field">メールアドレス<input name="email" type="email" autoComplete="email" required /></label><label className="field">パスワード<input name="password" type="password" autoComplete="new-password" minLength={12} required /></label><button className="button" disabled={busy}>{busy ? '送信中…' : '確認メールを送信'}</button></form></section>}
    {capabilities.billing && <BillingAccount />}
    <section className="panel settings-panel"><div className="panel-heading"><div><span className="eyebrow">NOTIFICATIONS</span><h2>通知設定</h2></div></div><form onSubmit={save}><div className="panel-body">{preferenceKeys.map(key => { const index = (['predictions', 'changes', 'articles', 'billing'] as const).indexOf(key); return <label className="setting-row" key={key}><span><strong>{['対象レース告知・最終予想の公開', '評価変更・開催に関するお知らせ', '記事・動画・音声の更新', 'お支払いに関するお知らせ'][index]}</strong><small>{['予想対象レースの決定時と最終予想の公開時', '評価UP／DOWNや発走時刻の変更など', '新しいコンテンツが公開されたとき', '決済結果や契約の変更など'][index]}</small></span><input type="checkbox" checked={preferences[key]} onChange={e => setPreferences({ ...preferences, [key]: e.target.checked })} /></label>; })}</div><div className="panel-actions"><p>{capabilities.lineNotifications ? 'LINE連携済みの場合、選択した通知をLINEで受け取れます。' : '選択したお知らせを会員ページで確認できます。'}</p><button className="button" disabled={busy}>{busy ? '保存中…' : '設定を保存'}<Check size={17} /></button></div></form></section>
    <section className="panel"><div className="panel-heading"><h2>同意履歴</h2></div><div className="table-scroll"><table><thead><tr><th>確認事項</th><th>バージョン</th><th>同意日時（JST）</th></tr></thead><tbody>{me.consents.map((c, i) => <tr key={i}><td>{({ TERMS: '利用規約', PRIVACY: 'プライバシーポリシー', AGE_20: '20歳以上の確認' })[c.documentType] ?? c.documentType}</td><td>{c.version}</td><td>{formatDate(c.acceptedAt)}</td></tr>)}</tbody></table></div></section>
    {me.role === 'MEMBER' && <AccountClosure onClosed={refresh} />}
  </>;
}

function Security({ me, refresh }: { me: Me; refresh: () => Promise<void> }) {
  const [secret, setSecret] = useState(''); const [code, setCode] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const [factorId, setFactorId] = useState('');
  async function enroll() { setBusy(true); setError(''); try { const result = await api<{ secret: string; factorId?: string }>('auth/mfa/enroll', 'POST'); setSecret(result.secret); setFactorId(result.factorId ?? ''); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function verify(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { await api('auth/mfa/verify', 'POST', { code, ...(factorId ? { factorId } : {}) }); setSecret(''); setFactorId(''); setCode(''); await refresh(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  return <><Heading eyebrow="SECURITY" title="二段階認証" description="認証アプリのコードで、アカウントを保護します。" /><section className="panel security-panel"><div className="panel-heading"><h2>認証アプリ</h2><span className="status-tag">{me.aal === 2 ? '認証済み' : me.mfaEnabled ? 'コード確認が必要' : '未設定'}</span></div><div className="panel-body"><Notice text={error} error />{me.aal === 2 ? <div className="success-state"><ShieldCheck size={36} /><h3>二段階認証が完了しています</h3><p>このログインセッションでは認証済みです。</p><Link className="button" href={me.role === 'ADMIN' ? '/admin' : me.role === 'EXPERT' ? '/expert' : '/account'}>アカウントに戻る<ArrowRight size={16} /></Link></div> : <>{me.mfaRequired && <p>管理者・専門家の操作には二段階認証が必要です。</p>}{!me.mfaEnabled && !secret && <><p>認証アプリにアカウントを追加し、表示された6桁のコードを入力してください。</p><button className="button" onClick={() => void enroll()} disabled={busy}>設定を始める</button></>}{secret && <div className="setup-secret"><strong>1. 認証アプリにキーを登録</strong><p>時間ベースのアカウントとして、以下のキーを登録してください。</p><code>{secret}</code><p>このキーは他の人と共有しないでください。</p></div>}{(secret || me.mfaEnabled) && <form onSubmit={verify}><label className="field">認証コード<input value={code} onChange={e => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))} inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" required placeholder="000000" /></label><button className="button" disabled={busy}>{busy ? '確認中…' : 'コードを確認'}</button></form>}</>}</div></section></>;
}

function AccessGate({ me, allowed, children }: { me: Me; allowed: string[]; children: ReactNode }) {
  if (!allowed.includes(me.role)) return <><Heading eyebrow="ACCESS" title="閲覧権限がありません" /><p>この画面は担当者向けです。</p><Link href="/account" className="button">マイページへ</Link></>;
  if (me.mfaRequired && me.aal !== 2) return <><Heading eyebrow="SECURITY" title="二段階認証を完了してください" description="管理・専門家向けの操作を始める前に、認証アプリで確認します。" /><Link href="/security" className="button">二段階認証へ<ArrowRight size={17} /></Link></>;
  return <>{children}</>;
}
function Expert({ me }: { me: Me }) { return <AccessGate me={me} allowed={['ADMIN', 'EXPERT']}><ExpertContent userId={me.id} /></AccessGate>; }
function ExpertContent({ userId }: { userId: string }) {
  const search = useSearchParams(); const [selected, setSelected] = useState<string | null>(() => search.get('race'));
  const [races, setRaces] = useState<Race[]>([]); const [error, setError] = useState('');
  useEffect(() => { api<{ items: Race[] }>('expert/races').then(v => setRaces(v.items)).catch(e => setError(e.message)); }, []);
  if (selected) return <AssessmentEditor key={selected} raceId={selected} userId={userId} onClose={() => setSelected(null)} />;
  return <><Heading eyebrow="EXPERT WORKSPACE" title="担当レース" description="あなたが担当するレースを確認できます。" /><Notice text={error} error /><section className="panel">{races.length ? races.map(race => <div className="race-row" key={race.id}><div className="race-number">{race.number}<small>R</small></div><div className="race-info"><span className="muted">{race.venue} · {formatDate(race.startsAt)}</span><h3>{race.name}</h3></div><button className="button secondary small" onClick={() => setSelected(race.id)}>評価を入力</button></div>) : <Empty title="担当レースはありません">レースが割り当てられると、こちらに表示されます。</Empty>}</section></>;
}
function Admin({ me, path }: { me: Me; path: string }) { return <AccessGate me={me} allowed={['/admin', '/admin/races', '/admin/publication-schedules', '/admin/results', '/admin/notifications', '/admin/incidents'].includes(path) ? ['ADMIN', 'OPERATOR'] : ['ADMIN']}>{path === '/admin/races' ? <RaceManager /> : path === '/admin/publication-schedules' ? <PublicationSchedules /> : path === '/admin/results' ? <AdminResults /> : path === '/admin/acquisition' ? <AcquisitionManager /> : path === '/admin/settings' ? <AdminSettings /> : path === '/admin/notifications' ? <AdminNotifications /> : path === '/admin/incidents' ? <AdminIncidents role={me.role} /> : path === '/admin/readiness' ? <AdminReadiness /> : path === '/admin/backups' ? <AdminBackups /> : path === '/admin/account-closures' ? <AdminAccountClosures /> : path === '/admin/billing' ? <AdminBilling /> : <AdminContent key={path} path={path} me={me} />}</AccessGate>; }
type UserRow = { id: string; displayName: string; email: string | null; emailVerifiedAt: string | null; registrationMethod: string; lineAccount: { unlinkedAt: string | null } | null; role: string; createdAt: string };
type AuditRow = { id: string; action: string; reason: string; createdAt: string; requestId: string };
function Funnel({ summary }: { summary: Summary }) {
  const recent = summary.funnel.last30Days;
  const stages: [string, keyof FunnelCounts][] = [['無料登録', 'registered'], ['本人確認', 'identityReady'], ['LINE準備', 'lineReady'], ['料金閲覧', 'planViewed'], ['申込確認', 'checkoutReviewed'], ['有料化', 'paid']];
  const rate = (value: number, total: number) => total ? Math.round(value / total * 100) : 0;
  return <section className="panel funnel-panel" aria-labelledby="member-funnel-title"><div className="panel-heading"><div><span className="eyebrow">MEMBER FUNNEL</span><h2 id="member-funnel-title">会員転換ファネル</h2></div><span className="count-tag">直近30日登録</span></div><div className="panel-body"><div className="funnel-list">{stages.map(([label, key]) => <div className="funnel-row" key={key}><div><strong>{label}</strong><small>全期間 {summary.funnel.all[key]}人</small></div><div className="funnel-meter" aria-hidden="true"><span style={{ width: `${rate(recent[key], recent.registered)}%` }} /></div><b>{recent[key]}<small>人 · {rate(recent[key], recent.registered)}%</small></b></div>)}</div><p className="muted funnel-note">料金閲覧と申込確認は、ログイン会員の初回到達だけを集計します。{summary.funnel.trackingStartsAt ? `計測開始：${formatDate(summary.funnel.trackingStartsAt)} JST` : '計測データはまだありません。'}</p></div></section>;
}
function AcquisitionReport({ summary }: { summary: Summary }) {
  const rows = summary.acquisition.last30Days;
  const rate = (row: AcquisitionRow) => row.registered ? Math.round(row.paid / row.registered * 100) : 0;
  return <section className="panel acquisition-panel" aria-labelledby="acquisition-title"><div className="panel-heading"><div><span className="eyebrow">ACQUISITION</span><h2 id="acquisition-title">登録流入別の有料化</h2></div><span className="count-tag">直近30日</span></div>{rows.length ? <div className="table-scroll"><table><thead><tr><th>流入元</th><th>キャンペーン</th><th>無料登録</th><th>有料化</th><th>率</th></tr></thead><tbody>{rows.map(row => <tr key={`${row.source}:${row.medium ?? ''}:${row.campaign ?? ''}`}><td><strong>{row.source}</strong><small>{row.medium ?? '未設定'}</small></td><td>{row.campaign ?? '未設定'}</td><td>{row.registered}人</td><td>{row.paid}人</td><td>{rate(row)}%</td></tr>)}</tbody></table></div> : <div className="panel-body"><p className="muted">直近30日の流入付き登録はまだありません。</p></div>}<div className="panel-foot">UTM付き登録URLの例：<code>/register?utm_source=lp&amp;utm_medium=owned&amp;utm_campaign=launch</code>{summary.acquisition.legacyMembers > 0 && <span> · 計測開始前の会員 {summary.acquisition.legacyMembers}人</span>}</div></section>;
}
type RehearsalStep = { key: string; label: string; state: 'DONE' | 'CURRENT' | 'WAITING' | 'BLOCKED' | 'NOT_DUE'; detail: string };
type RehearsalSummary = { ready: number; blocked: number; total: number; preflight: { csvImportEnabled: boolean; predictionPublicationEnabled: boolean; lineNotificationsEnabled: boolean; lineConfigured: boolean } };
type OperationsRace = { id: string; venue: string; number: number; name: string; status: string; startsAt: string; secondsRemaining: number; deadlineState: 'UPCOMING' | 'DUE_SOON' | 'OVERDUE'; assignments: { id: string; displayName: string; active: boolean }[]; entries: { total: number; paddockCompleted: number }; announcement: { version: number; publishedAt: string; eventStatus: string | null } | null; prediction: { version: number; status: string; publishedAt: string; eventStatus: string | null } | null; notification: { queued: number; sent: number; failed: number }; result: { version: number; confirmedAt: string } | null; warnings: string[]; rehearsal: { status: 'BLOCKED' | 'COMPLETE' | 'READY' | 'IN_PROGRESS'; done: number; total: number; nextStep: string | null; steps: RehearsalStep[] } };
function OperationsBoard({ role }: { role: string }) {
  const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Tokyo' }); const [date, setDate] = useState(today); const [items, setItems] = useState<OperationsRace[]>([]); const [alerts, setAlerts] = useState(0); const [rehearsal, setRehearsal] = useState<RehearsalSummary | null>(null); const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const [error, setError] = useState(''); const [lastUpdated, setLastUpdated] = useState<string | null>(null); const [clock, setClock] = useState(Date.now()); const requestSequence = useRef(0);
  const load = useCallback(async (initial = false) => { const sequence = ++requestSequence.current; if (initial) setLoading(true); else setRefreshing(true); try { const value = await api<{ items: OperationsRace[]; alerts: number; generatedAt: string; rehearsal: RehearsalSummary }>(`admin/operations?date=${date}`); if (sequence !== requestSequence.current) return; setItems(value.items); setAlerts(value.alerts); setRehearsal(value.rehearsal); setLastUpdated(value.generatedAt); setError(''); } catch (e) { if (sequence === requestSequence.current) setError((e as Error).message); } finally { if (sequence === requestSequence.current) { setLoading(false); setRefreshing(false); } } }, [date]);
  useEffect(() => { void load(true); const refresh = window.setInterval(() => { if (document.visibilityState === 'visible') void load(); }, 30000); const tick = window.setInterval(() => setClock(Date.now()), 1000); const visible = () => { setClock(Date.now()); if (document.visibilityState === 'visible') void load(); }; document.addEventListener('visibilitychange', visible); return () => { requestSequence.current++; window.clearInterval(refresh); window.clearInterval(tick); document.removeEventListener('visibilitychange', visible); }; }, [load]);
  const moveDate = (days: number) => { const value = new Date(`${date}T12:00:00+09:00`); value.setUTCDate(value.getUTCDate() + days); setDate(value.toLocaleDateString('sv-SE', { timeZone: 'Asia/Tokyo' })); };
  const secondsLeft = (race: OperationsRace) => Math.floor((new Date(race.startsAt).getTime() - clock) / 1000);
  const remaining = (race: OperationsRace) => { const seconds = secondsLeft(race); if (seconds <= 0) return '発走時刻を経過'; const minutes = Math.ceil(seconds / 60); return minutes < 60 ? `発走まで${minutes}分` : `発走まで${Math.floor(minutes / 60)}時間${minutes % 60}分`; };
  const deadline = (race: OperationsRace) => { const seconds = secondsLeft(race); return seconds <= 0 ? 'overdue' : seconds <= 1800 ? 'due_soon' : 'upcoming'; };
  const stale = !!lastUpdated && clock - new Date(lastUpdated).getTime() > 90000;
  const updateTime = lastUpdated ? new Intl.DateTimeFormat('ja-JP', { timeZone: 'Asia/Tokyo', hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(new Date(lastUpdated)) : '未取得';
  const preflight = rehearsal ? [['CSV取込', rehearsal.preflight.csvImportEnabled], ['予想公開', rehearsal.preflight.predictionPublicationEnabled], ['LINE通知', rehearsal.preflight.lineNotificationsEnabled], ['LINE設定', rehearsal.preflight.lineConfigured]] as const : [];
  const stateLabel: Record<RehearsalStep['state'], string> = { DONE: '完了', CURRENT: '次に確認', WAITING: '待機', BLOCKED: '要対応', NOT_DUE: '発走後' };
  return <section className="panel operations-board" aria-labelledby="operations-board-title"><div className="panel-heading operations-heading"><div><span className="eyebrow">LIVE OPERATIONS</span><h2 id="operations-board-title">開催日運用ボード</h2></div><span className={`count-tag ${alerts ? 'warning' : ''}`}>{alerts}件の警告</span></div><div className="operations-live-status" aria-live="polite"><span className={`live-indicator ${error || stale ? 'stale' : ''}`} /> <strong>{error ? '更新に失敗' : stale ? '情報が古くなっています' : refreshing ? '更新中…' : '自動更新中'}</strong><small>最終更新 {updateTime} JST</small><button className="button secondary small" disabled={refreshing} onClick={() => void load()}><RefreshCw size={15} className={refreshing ? 'spin' : ''} />今すぐ更新</button></div>{rehearsal && <section className="rehearsal-overview" aria-labelledby="rehearsal-title"><div><span className="eyebrow">REHEARSAL</span><h3 id="rehearsal-title">開催日リハーサル</h3><p>実データの状態から、告知から結果確定までの確認順を表示します。</p></div><div className="rehearsal-counts"><strong>{rehearsal.ready}<small>準備完了</small></strong><strong className={rehearsal.blocked ? 'danger-text' : ''}>{rehearsal.blocked}<small>要対応</small></strong><strong>{rehearsal.total}<small>対象レース</small></strong></div><div className="preflight-list" aria-label="運用機能の事前確認">{preflight.map(([label, ready]) => <span className={ready ? 'ready' : 'blocked'} key={label}>{ready ? <Check size={14} /> : <X size={14} />}{label}</span>)}</div></section>}<div className="operations-toolbar"><button className="icon-button" aria-label="前日" onClick={() => moveDate(-1)}><ChevronRight className="flip" size={18} /></button><label>運用日<input type="date" value={date} onChange={e => setDate(e.target.value)} /></label><button className="icon-button" aria-label="翌日" onClick={() => moveDate(1)}><ChevronRight size={18} /></button>{date !== today && <button className="text-link" onClick={() => setDate(today)}>今日</button>}</div><Notice text={error} error />{loading ? <div className="panel-body" role="status">運用状況を読み込み中…</div> : !items.length ? <Empty title="この日のレースはありません">別の日付を選ぶか、レース管理から対象レースを登録してください。</Empty> : <div className="operations-list">{items.map(race => <article className={`operation-race ${race.warnings.length ? 'needs-attention' : ''}`} key={race.id}><div className="operation-race-head"><div className="race-number">{race.number}<small>R</small></div><div><span className="muted">{race.venue} · {formatDate(race.startsAt)} JST</span><h3>{race.name}</h3></div><span className={`deadline-tag ${deadline(race)}`}>{remaining(race)}</span></div><div className="operation-progress"><div><span>担当</span><strong>{race.assignments.map(item => item.displayName).join('、') || '未設定'}</strong></div><div><span>告知</span><strong>{race.announcement ? `公開済み v${race.announcement.version}` : '未告知'}</strong></div><div><span>パドック</span><strong>{race.entries.paddockCompleted} / {race.entries.total}頭</strong></div><div><span>最終予想</span><strong>{race.prediction ? `公開済み v${race.prediction.version}` : '未公開'}</strong></div><div><span>通知</span><strong className={race.notification.failed ? 'danger-text' : ''}>送信{race.notification.sent}・待ち{race.notification.queued}・失敗{race.notification.failed}</strong></div><div><span>結果</span><strong>{race.result ? `確定 v${race.result.version}` : '未確定'}</strong></div></div><div className="rehearsal-checklist" aria-label={`${race.name}のリハーサル手順`}><div className="rehearsal-checklist-head"><strong>運用チェック {race.rehearsal.done}/{race.rehearsal.total}</strong><span className={`rehearsal-status ${race.rehearsal.status.toLowerCase()}`}>{race.rehearsal.status === 'COMPLETE' ? '全工程完了' : race.rehearsal.status === 'READY' ? '発走準備完了' : race.rehearsal.status === 'BLOCKED' ? '要対応あり' : '進行中'}</span></div><ol>{race.rehearsal.steps.map(step => <li className={step.state.toLowerCase()} key={step.key}><span className="step-icon">{step.state === 'DONE' ? <Check size={15} /> : step.state === 'BLOCKED' ? <X size={15} /> : <span />}</span><div><strong>{step.label}</strong><small>{step.detail}</small></div><b>{stateLabel[step.state]}</b></li>)}</ol></div>{race.warnings.length > 0 && <div className="operation-warnings" role="status">{race.warnings.map(warning => <span key={warning}>{warning}</span>)}</div>}<div className="operation-actions"><Link className="button secondary small" href="/admin/races">レース管理</Link>{role === 'ADMIN' && <Link className="button secondary small" href={`/expert?race=${race.id}`}>評価・公開</Link>}<Link className="button secondary small" href="/admin/notifications">通知</Link>{secondsLeft(race) <= 0 && <Link className="button secondary small" href="/admin/results">結果</Link>}</div></article>)}</div>}</section>;
}
function AdminContent({ path, me }: { path: string; me: Me }) {
  const [summary, setSummary] = useState<Summary | null>(null); const [users, setUsers] = useState<UserRow[]>([]); const [audits, setAudits] = useState<AuditRow[]>([]);
  const [error, setError] = useState(''); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true);
  useEffect(() => { setLoading(true); setError(''); const run = async () => {
    try { if (path === '/admin') setSummary(await api<Summary>('admin/summary'));
      else if (path === '/admin/users') { const v = await api<{ items: UserRow[]; total: number }>(`admin/users?page=${page}`); setUsers(v.items); setTotal(v.total); }
      else { const v = await api<{ items: AuditRow[]; total: number }>(`admin/audit?page=${page}`); setAudits(v.items); setTotal(v.total); }
    } catch (e) { setError((e as Error).message); } finally { setLoading(false); }
  }; void run(); }, [path, page]);
  return <><Heading eyebrow="ADMINISTRATION" title={path === '/admin/users' ? '会員管理' : path === '/admin/audit' ? '操作履歴' : '管理ダッシュボード'} description={path === '/admin' ? '会員と運用の状況を確認します。' : undefined} /><Notice text={error} error />
    {loading ? <p role="status">読み込み中…</p> : path === '/admin' && summary ? <><div className="stats-grid">{[['登録会員', summary.members, '人'], ['閲覧権限あり', summary.entitled, '人'], ['公開待ちレース', summary.racesNeedingPrediction, '件'], ['結果未確定', summary.resultsPending, '件'], ['通知待ち', summary.queuedNotifications, '件'], ['登録レース', summary.races, '件'], ['操作履歴', summary.auditCount, '件']].map(([label, count, unit]) => <section className="stat" key={label}><span>{label}</span><strong>{count}<small>{unit}</small></strong></section>)}</div><OperationsBoard role={me.role} /><Funnel summary={summary} /><AcquisitionReport summary={summary} />{Object.values(summary.operations ?? {}).some(value => !value) && <div className="notice error" role="alert">停止中の機能があります。運用・連携設定を確認してください。</div>}<section className="panel"><div className="panel-heading"><h2>運用メニュー</h2></div><Link className="action-row" href="/admin/results"><BarChart3 size={23} /><div><strong>結果・成績管理</strong><small>着順、払戻、公開版別成績を確定</small></div><ArrowRight size={18} /></Link><Link className="action-row" href="/admin/incidents"><ShieldAlert size={23} /><div><strong>障害対応チェック</strong><small>停止・遅延の検知と復旧手順を確認</small></div><ArrowRight size={18} /></Link>{me.role === 'ADMIN' && <><Link className="action-row" href="/admin/readiness"><ClipboardCheck size={23} /><div><strong>本番準備チェック</strong><small>公開前の不足項目と対応先を確認</small></div><ArrowRight size={18} /></Link><Link className="action-row" href="/admin/backups"><DatabaseBackup size={23} /><div><strong>バックアップ・復元確認</strong><small>隔離復元の実施結果と整合性を確認</small></div><ArrowRight size={18} /></Link><Link className="action-row" href="/admin/account-closures"><UserRoundX size={23} /><div><strong>退会・保持記録</strong><small>利用停止済み会員と履歴保持方針を確認</small></div><ArrowRight size={18} /></Link><Link className="action-row" href="/admin/settings"><Settings2 size={23} /><div><strong>運用・連携設定</strong><small>LINE、通知方針、緊急停止を管理</small></div><ArrowRight size={18} /></Link><Link className="action-row" href="/admin/users"><Users size={23} /><div><strong>会員管理</strong><small>登録会員とロールを確認</small></div><ArrowRight size={18} /></Link><Link className="action-row" href="/admin/audit"><Clock3 size={23} /><div><strong>操作履歴</strong><small>登録・設定変更・認証の履歴を確認</small></div><ArrowRight size={18} /></Link></>}<div className="panel-foot">レース登録は「レース管理」、評価・最終予想・公開は「担当レース」で操作できます。</div></section></> : <section className="panel"><div className="table-scroll"><table><thead><tr>{(path === '/admin/users' ? ['表示名', 'メールアドレス', 'ロール', '登録日時（JST）'] : ['操作', '理由', '日時（JST）', 'リクエストID']).map(label => <th key={label}>{label}</th>)}</tr></thead><tbody>{path === '/admin/users' ? users.map(user => <tr key={user.id}><td>{user.displayName}</td><td>{user.email ?? '未設定'}<small>{user.emailVerifiedAt ? '確認済み' : user.registrationMethod === 'LINE' ? 'LINE登録' : '確認待ち'}</small></td><td><span className="role-tag">{roleLabels[user.role]}</span></td><td>{formatDate(user.createdAt)}</td></tr>) : audits.map(audit => <tr key={audit.id}><td>{audit.action}</td><td>{audit.reason}</td><td>{formatDate(audit.createdAt)}</td><td className="mono">{audit.requestId}</td></tr>)}</tbody></table></div><div className="pagination"><span>全{total}件 · {page}ページ</span><button className="button secondary small" disabled={page <= 1} onClick={() => setPage(page - 1)}>前へ</button><button className="button secondary small" disabled={page * 20 >= total} onClick={() => setPage(page + 1)}>次へ</button></div></section>}
  </>;
}
function legalDocumentLabel(document: LegalDocument) { return `${document.title}${document.status === 'DRAFT' ? '（開発用）' : ''}`; }

function Policy({ privacy }: { privacy: boolean }) {
  const document = privacy ? legalDocuments.privacy : legalDocuments.terms;
  return <><Heading eyebrow={document.status === 'PUBLISHED' ? 'LEGAL DOCUMENT' : 'DEVELOPMENT DOCUMENT'} title={legalDocumentLabel(document)} description={`文書バージョン：${document.version}${document.effectiveDate ? ` ・ 施行日：${document.effectiveDate}` : ''}`} /><section className="panel policy">{document.status === 'DRAFT' && <h2>ローカル動作確認のための文書です</h2>}{document.introduction.map(paragraph => <p key={paragraph}>{paragraph}</p>)}{document.sections.map(section => <div key={section.heading}><h3>{section.heading}</h3>{section.paragraphs.map(paragraph => <p key={paragraph}>{paragraph}</p>)}</div>)}<Link className="text-link" href="/register">登録画面へ戻る<ArrowRight size={16} /></Link></section></>;
}
